// ============================================================
// NORMALIZACIÃ“N DE UPLINKS TTN
// Proyecto IoT agrÃ­cola
//
// Convierte el JSON completo recibido desde TTN en una
// estructura interna comÃºn para el resto del sistema.
//
// Dispositivos actuales:
//   rs485-lb-01     -> Sensor NPK #1
//   rs485-lb-02     -> Sensor NPK #2
//   rs485-lb-03     -> Sensor NPK #3
//   rak7431-byx-01  -> Sensor agroclimÃ¡tico BYX #1
//
// El diseÃ±o permite incorporar nuevas variables del BYX
// sin modificar la arquitectura general.
// ============================================================


// ------------------------------------------------------------
// 1. Validar estructura bÃ¡sica del mensaje de TTN
// ------------------------------------------------------------

if (!msg.payload || !msg.payload.end_device_ids) {
    node.warn("Uplink descartado: no contiene end_device_ids");
    return null;
}

if (!msg.payload.uplink_message) {
    node.warn("Uplink descartado: no contiene uplink_message");
    return null;
}

if (!msg.payload.uplink_message.decoded_payload) {
    node.warn("Uplink descartado: no contiene decoded_payload");
    return null;
}


// ------------------------------------------------------------
// 2. Extraer informaciÃ³n general del uplink
// ------------------------------------------------------------

const deviceId = msg.payload.end_device_ids.device_id;
const receivedAt = msg.payload.received_at;
const decoded = msg.payload.uplink_message.decoded_payload;


// ------------------------------------------------------------
// 3. CatÃ¡logo de dispositivos conocidos
// ------------------------------------------------------------

const devices = {

    "rs485-lb-01": {
        node: "npk-01",
        sensorType: "npk",
        description: "Sensor NPK #1"
    },

    "rs485-lb-02": {
        node: "npk-02",
        sensorType: "npk",
        description: "Sensor NPK #2"
    },

    "rs485-lb-03": {
        node: "npk-03",
        sensorType: "npk",
        description: "Sensor NPK #3"
    },

    "rak7431-byx-01": {
        node: "byx-01",
        sensorType: "environment",
        description: "Sensor agroclimÃ¡tico BYX #1"
    }

};


// ------------------------------------------------------------
// 4. Verificar que conocemos el dispositivo
// ------------------------------------------------------------

if (!devices[deviceId]) {
    node.warn(
        "Uplink descartado: dispositivo no registrado -> " +
        deviceId
    );
    return null;
}

const device = devices[deviceId];


// ------------------------------------------------------------
// 5. Procesar segÃºn el tipo de sensor
// ------------------------------------------------------------

let measurements = {};
let units = {};


// ============================================================
// SENSOR NPK
// ============================================================

if (device.sensorType === "npk") {

    // Las tres variables deben existir.
    // Se compara contra undefined porque 0 es una lectura vÃ¡lida.

    if (
        decoded.nitrogen === undefined ||
        decoded.phosphorus === undefined ||
        decoded.potassium === undefined
    ) {
        node.warn(
            "Uplink NPK descartado: faltan variables en " +
            deviceId
        );
        return null;
    }

    // AÃ±adir las mediciones NPK
    measurements.nitrogen = Number(decoded.nitrogen);
    measurements.phosphorus = Number(decoded.phosphorus);
    measurements.potassium = Number(decoded.potassium);

    // Unidades NPK
    units.nitrogen = "mg/kg";
    units.phosphorus = "mg/kg";
    units.potassium = "mg/kg";
}


// ============================================================
// SENSOR AGROCLIMÃTICO BYX
// ============================================================

else if (device.sensorType === "environment") {

    // --------------------------------------------------------
    // Variables actuales obligatorias
    //
    // Actualmente el RAK7431 estÃ¡ leyendo del BYX:
    //   0x0000 -> Humedad
    //   0x0001 -> Temperatura
    // --------------------------------------------------------

    if (
        decoded.humidity === undefined ||
        decoded.temperature === undefined
    ) {
        node.warn(
            "Uplink BYX descartado: faltan humedad o temperatura en " +
            deviceId
        );
        return null;
    }


    // Humedad
    measurements.humidity = Number(decoded.humidity);
    units.humidity = "%RH";

    // Temperatura
    measurements.temperature = Number(decoded.temperature);
    units.temperature = "Â°C";


    // --------------------------------------------------------
    // Variables futuras del BYX
    //
    // Estas variables SOLO se aÃ±aden si realmente aparecen
    // dentro del decoded_payload enviado por TTN.
    // --------------------------------------------------------


    // PM2.5
    if (decoded.pm25 !== undefined) {
        measurements.pm25 = Number(decoded.pm25);
        units.pm25 = "Âµg/mÂ³";
    }


    // CO2
    if (decoded.co2 !== undefined) {
        measurements.co2 = Number(decoded.co2);
        units.co2 = "ppm";
    }


    // Gas
    if (decoded.gas !== undefined) {
        measurements.gas = Number(decoded.gas);
        units.gas = "ppm";
    }


    // Iluminancia
    if (decoded.illuminance !== undefined) {
        measurements.illuminance = Number(decoded.illuminance);
        units.illuminance = "lux";
    }


    // PM10
    if (decoded.pm10 !== undefined) {
        measurements.pm10 = Number(decoded.pm10);
        units.pm10 = "Âµg/mÂ³";
    }


    // PresiÃ³n atmosfÃ©rica
    if (decoded.pressure !== undefined) {
        measurements.pressure = Number(decoded.pressure);
        units.pressure = "kPa";
    }


    // Ruido
    if (decoded.noise !== undefined) {
        measurements.noise = Number(decoded.noise);
        units.noise = "dB";
    }
}


// ============================================================
// TIPO DE SENSOR NO SOPORTADO
// ============================================================

else {

    node.warn(
        "Uplink descartado: tipo de sensor no soportado -> " +
        device.sensorType
    );

    return null;
}


// ------------------------------------------------------------
// 6. Validar que las mediciones sean numÃ©ricas
// ------------------------------------------------------------

for (const key in measurements) {

    if (!Number.isFinite(measurements[key])) {

        node.warn(
            "Uplink descartado: mediciÃ³n no numÃ©rica -> " +
            key +
            " en " +
            deviceId
        );

        return null;
    }
}


// ------------------------------------------------------------
// 7. Construir mensaje normalizado
// ------------------------------------------------------------

msg.payload = {

    device_id: deviceId,

    node: device.node,

    sensor_type: device.sensorType,

    description: device.description,

    timestamp: receivedAt,

    measurements: measurements,

    units: units

};


// ------------------------------------------------------------
// 8. Entregar mensaje al siguiente nodo
// ------------------------------------------------------------

return msg;

// ============================================================
// PREPARAR DATOS PARA INFLUXDB
// Proyecto IoT agrÃ­cola
//
// Convierte las mediciones normalizadas en el formato esperado
// por el nodo InfluxDB.
//
// Compatible actualmente con:
//   - Sensores NPK
//   - Sensor agroclimÃ¡tico BYX
//
// La funciÃ³n es genÃ©rica: cualquier nueva mediciÃ³n numÃ©rica
// incluida en "measurements" se enviarÃ¡ automÃ¡ticamente.
// ============================================================


// ------------------------------------------------------------
// 1. Validar estructura bÃ¡sica
// ------------------------------------------------------------

const data = msg.payload;

if (!data || !data.measurements) {
    node.warn("Dato descartado: no existe measurements");
    return null;
}


// ------------------------------------------------------------
// 2. Construir dinÃ¡micamente los fields de InfluxDB
// ------------------------------------------------------------

const fields = {};

for (const key in data.measurements) {

    const value = Number(data.measurements[key]);

    // Solo almacenar valores numÃ©ricos vÃ¡lidos
    if (Number.isFinite(value)) {
        fields[key] = value;
    }
}


// ------------------------------------------------------------
// 3. Comprobar que exista al menos una mediciÃ³n vÃ¡lida
// ------------------------------------------------------------

if (Object.keys(fields).length === 0) {
    node.warn(
        "Dato descartado: no existen mediciones numÃ©ricas vÃ¡lidas"
    );
    return null;
}


// ------------------------------------------------------------
// 4. Crear tags
//
// Los tags permiten posteriormente filtrar los datos en
// InfluxDB y Grafana.
// ------------------------------------------------------------

const tags = {
    device_id: String(data.device_id),
    node: String(data.node),
    sensor_type: String(data.sensor_type)
};


// ------------------------------------------------------------
// 5. Procesar timestamp
// ------------------------------------------------------------

const timestamp = new Date(data.timestamp);

if (Number.isNaN(timestamp.getTime())) {
    node.warn("Dato descartado: timestamp invÃ¡lido");
    return null;
}


// ------------------------------------------------------------
// 6. Preparar mensaje para InfluxDB
// ------------------------------------------------------------

msg.timestamp = timestamp.getTime();

msg.payload = [
    fields,
    tags
];


// ------------------------------------------------------------
// 7. Entregar al nodo InfluxDB
// ------------------------------------------------------------

return msg;
